def top_words(text, k):
    if not text or k <= 0:
        return []

    counts = {}
    for word in text.lower().split():
        counts[word] = counts.get(word, 0) + 1

    ranked = sorted(counts.items(), key=lambda item: (-item[1], item[0]))
    return ranked[:k]
