class MinStack:
    def __init__(self):
        self._stack = []  # list of (value, current_min) tuples

    def push(self, x):
        if self._stack:
            current_min = self._stack[-1][1]
        else:
            current_min = x
        new_min = min(x, current_min)
        self._stack.append((x, new_min))

    def pop(self):
        if not self._stack:
            raise IndexError("pop from empty stack")
        return self._stack.pop()[0]

    def min(self):
        if not self._stack:
            raise IndexError("min from empty stack")
        return self._stack[-1][1]

