def gen(n):
    results = []
    def helper(s, open_count, close_count):
        if len(s) == 2 * n:
            results.append(s)
            return
        if open_count < n:
            helper(s + '(', open_count + 1, close_count)
        if close_count < open_count:
            helper(s + ')', open_count, close_count + 1)
    helper('', 0, 0)
    return results
