def coins(amount, denoms):
    dp = [float('inf')] * (amount + 1)
    dp[0] = 0
    for i in range(1, amount + 1):
        for d in denoms:
            if d <= i and dp[i - d] != float('inf'):
                dp[i] = min(dp[i], dp[i - d] + 1)
    return dp[amount] if dp[amount] != float('inf') else -1
