def caesar(s, k):
    result = []
    for ch in s:
        if 'A' <= ch <= 'Z':
            result.append(chr((ord(ch) - ord('A') + k) % 26 + ord('A')))
        elif 'a' <= ch <= 'z':
            result.append(chr((ord(ch) - ord('a') + k) % 26 + ord('a')))
        else:
            result.append(ch)
    return ''.join(result)
